// ============================================================
// WF2 — GEOCODE FALLBACK
// If Google Maps Geocoding failed (no results), fall back to
// known area coordinates for major Islamabad sectors.
// ============================================================
const geocodeResult = $('Geocode Location').first().json;
const intent = $('WF2 — HTTP Trigger').first().json.body;
const parsedIntent = intent.output || intent;

const geocodeSuccess = geocodeResult.results && geocodeResult.results.length > 0;

if (geocodeSuccess) {
  // Pass through normally
  return [{ json: {
    lat: geocodeResult.results[0].geometry.location.lat,
    lng: geocodeResult.results[0].geometry.location.lng,
    formatted_address: geocodeResult.results[0].formatted_address,
    source: 'google_maps'
  }}];
}

// Fallback: known coordinates for Islamabad sectors
const areaFallbackMap = {
  'g-13': { lat: 33.6557, lng: 73.0138 },
  'g-14': { lat: 33.6490, lng: 73.0050 },
  'g-11': { lat: 33.6844, lng: 73.0066 },
  'f-10': { lat: 33.7076, lng: 73.0287 },
  'f-11': { lat: 33.7183, lng: 73.0234 },
  'i-8':  { lat: 33.6715, lng: 73.0752 },
  'i-9':  { lat: 33.6644, lng: 73.0848 },
  'e-11': { lat: 33.7386, lng: 73.0124 },
  'islamabad': { lat: 33.6844, lng: 73.0479 }
};

const locationKey = (parsedIntent.location || '').toLowerCase().replace(/\s+/g, '-');
const matched = Object.keys(areaFallbackMap).find(k => locationKey.includes(k));
const coords = matched ? areaFallbackMap[matched] : areaFallbackMap['islamabad'];

console.log('⚠️ Maps API fallback triggered for:', parsedIntent.location, '→', matched || 'islamabad default');

return [{ json: {
  lat: coords.lat,
  lng: coords.lng,
  formatted_address: parsedIntent.location + ', Islamabad (fallback coordinates)',
  source: 'area_name_fallback',
  fallback_reason: 'Google Maps Geocoding returned no results'
}}];

// =========================
// INPUT SAFE HANDLING (FIXED)
// =========================
let inputRaw = $json.body;

if (!inputRaw) {
  inputRaw = "";
}

let input = "";

if (typeof inputRaw === "string") {
  input = inputRaw;
} else {
  input = JSON.stringify(inputRaw);
}

const text = input.toLowerCase();

// =========================
// BASE OUTPUT
// =========================
// Removed ": any" to fix the SyntaxError in JavaScript
const result = {};

// defaults
result.urgency = "medium";
result.preferred_time = "asap";
result.budget_sensitivity = "medium";
result.job_complexity = "basic";
result.detected_language = "english";

// =========================
// LANGUAGE DETECTION
// =========================
if (/[\u0600-\u06FF]/.test(input)) {
  result.detected_language = "urdu";
}
else if (
  text.includes("chahiye") ||
  text.includes("masla") ||
  text.includes("jaldi") ||
  text.includes("sasta") ||
  text.includes("bijli") ||
  text.includes("pani")
) {
  result.detected_language = "roman_urdu";
}

// =========================
// URGENCY DETECTION
// =========================
if (
  text.includes("urgent") ||
  text.includes("jaldi") ||
  text.includes("asap") ||
  text.includes("emergency") ||
  text.includes("abhi") ||
  text.includes("فوری")
) {
  result.urgency = "high";
}

// =========================
// BUDGET DETECTION
// =========================
if (
  text.includes("sasta") ||
  text.includes("cheap") ||
  text.includes("affordable") ||
  text.includes("kam budget")
) {
  result.budget_sensitivity = "high";
}

// =========================
// CITY DETECTION
// =========================
let city = null;

if (text.includes("karachi")) city = "Karachi";
else if (text.includes("lahore")) city = "Lahore";
else if (text.includes("islamabad")) city = "Islamabad";

if (city) {
  result.city = city;
}

// =========================
// AREA DETECTION (SAFE VERSION)
// =========================
let area = null;

if (text.includes("clifton block")) {
  area = "Clifton Block";
}
else if (text.includes("clifton")) {
  area = "Clifton";
}
else if (text.includes("dha phase")) {
  area = "DHA Phase";
}
else if (text.includes("johar town")) {
  area = "Johar Town";
}
else if (text.includes("model town")) {
  area = "Model Town";
}
else if (text.includes("bahria town")) {
  area = "Bahria Town";
}

if (area) {
  result.area = area;
}

// =========================
// LOCATION COMBINE
// =========================
if (city && area) {
  result.location = city + ", " + area;
}
else if (city) {
  result.location = city;
}
else if (area) {
  result.location = area;
}

// =========================
// SERVICE DETECTION (SAFE AI STYLE)
// =========================
let service = null;

if (
  text.includes("ac") ||
  text.includes("cooling") ||
  text.includes("compressor") ||
  text.includes("thanda")
) {
  service = "AC repair";
}
else if (
  text.includes("plumber") ||
  text.includes("pipe") ||
  text.includes("leak") ||
  text.includes("tap") ||
  text.includes("nalka")
) {
  service = "plumber";
}
else if (
  text.includes("electrician") ||
  text.includes("switch") ||
  text.includes("light") ||
  text.includes("bijli")
) {
  service = "electrician";
}
else if (
  text.includes("teacher") ||
  text.includes("tutor") ||
  text.includes("tuition") ||
  text.includes("math")
) {
  service = "tutor";
}
else if (
  text.includes("paint") ||
  text.includes("rang")
) {
  service = "painter";
}
else if (
  text.includes("carpenter") ||
  text.includes("wood")
) {
  service = "carpenter";
}
else if (
  text.includes("beautician") ||
  text.includes("makeup") ||
  text.includes("facial")
) {
  service = "beautician";
}

if (service) {
  result.service_type = service;
}

// =========================
// CONFIDENCE (SIMPLE SAFE SCORE)
// =========================
let confidence = 0;

if (service) confidence += 0.5;
if (city) confidence += 0.2;
if (area) confidence += 0.2;

result.confidence = confidence;

// =========================
// FINAL OUTPUT (n8n SAFE)
// =========================
return [
  {
    json: result
  }
];

// Get all incoming items
const items = $input.all();

// Create empty result object
let mergedData = {};

// Loop through all items
for (const item of items) {
  const data = item.json;

  // If nested under body, extract it
  if (data.body) {
    Object.assign(mergedData, data.body);
  } else {
    Object.assign(mergedData, data);
  }
}

return [
  {
    json: mergedData
  }
];

// Multi-Service Orchestration Logic
const output = $json.output;
const services = output.services || [output.primary_service];
const primaryService = output.primary_service || services[0];

// For single service: pass through directly
if (services.length === 1) {
  return [{
    json: {
      ...output,
      service_type: primaryService,
      is_multi_service: false
    }
  }];
}

// For multi-service: prepare aggregation payload
return [{
  json: {
    ...output,
    service_type: 'Multi-Service Package',
    primary_service: primaryService,
    services: services,
    is_multi_service: true,
    service_count: services.length
  }
}];

// WF2 Multi-Service Handler — Normalize services array
const intent = $json.body;
const services = intent.services || [intent.primary_service || intent.service_type];
const isMultiService = intent.is_multi_service || services.length > 1;

// Normalize: ensure we have actual service names, not "Multi-Service Package"
const normalizedServices = services.filter(s => s && s !== "Multi-Service Package");

if (normalizedServices.length === 0 && intent.primary_service) {
  normalizedServices.push(intent.primary_service);
}

return [{
  json: {
    ...intent,
    services: normalizedServices,
    service_type: isMultiService ? intent.primary_service : normalizedServices[0],
    is_multi_service: isMultiService,
    total_services: normalizedServices.length
  }
}];

// KHADMAT AI — 6-Factor Provider Scoring Algorithm with Multi-Service + Complexity Matching

const intent = $('WF2 — HTTP Trigger1').first().json.body;
const parsedIntent = intent.output || intent;

let requestedServices = parsedIntent.services || [];

if (requestedServices.length === 0) {
  const fallbackService = parsedIntent.primary_service || parsedIntent.service_type;
  if (fallbackService && fallbackService !== 'Multi-Service Package') {
    requestedServices = [fallbackService];
  }
}

requestedServices = requestedServices.filter(s => s && s !== 'Multi-Service Package');

if (requestedServices.length === 0) {
  return [{ json: {
    status: 'invalid_intent',
    message: 'No valid services found in request',
    received_intent: parsedIntent,
    workflow: 'WF2-ProviderMatching'
  }}];
}

const providers = $('Map Places → Provider Schema1').first().json.providers || [];

if (providers.length === 0) {
  return [{ json: {
    status: 'no_providers_available',
    message: 'Map Places node returned 0 providers',
    requested_services: requestedServices,
    workflow: 'WF2-ProviderMatching'
  }}];
}

// ── Complexity tier ordering ──────────────────────────────
const COMPLEXITY_ORDER = { 'basic': 0, 'intermediate': 1, 'complex': 2 };

const multiServiceResults = [];

for (const serviceType of requestedServices) {

  const scored = providers.map(provider => {

    // ── Service name match ────────────────────────────────
    const normalizedService = serviceType.toLowerCase();
    const providerServices = (provider.services || []).map(s => s.toLowerCase());
    const serviceMatch = providerServices.some(s =>
      s.includes(normalizedService) || normalizedService.includes(s)
    );

    // ── NEW: Complexity match ─────────────────────────────
    // Does provider's complexity_levels cover what the user needs?
    const requestedComplexity = parsedIntent.job_complexity || 'basic';
    const providerComplexityLevels = provider.complexity_levels || ['basic'];

    const complexityMatch = providerComplexityLevels.includes(requestedComplexity);

    // How far is the provider's max complexity from what's needed?
    const providerMaxComplexityRank = Math.max(
      ...providerComplexityLevels.map(c => COMPLEXITY_ORDER[c] ?? 0)
    );
    const requestedComplexityRank = COMPLEXITY_ORDER[requestedComplexity] ?? 0;
    const complexityGap = requestedComplexityRank - providerMaxComplexityRank;

    // ── Specialization score (now complexity-aware) ───────
    let specializationScore;
    if (!serviceMatch) {
      // Provider doesn't offer this service at all
      specializationScore = 20;
    } else if (complexityMatch) {
      // Exact service + handles the required complexity
      specializationScore = 100;
    } else if (complexityGap === 1) {
      // One tier short (e.g. provider does basic/intermediate, user needs complex)
      specializationScore = 55;
    } else {
      // Two tiers short (provider only does basic, user needs complex)
      specializationScore = 25;
    }

    // ── Distance Score ────────────────────────────────────
    const distanceScore = Math.max(0, 100 - (provider.distance_km * 10));

    // ── Availability Score ────────────────────────────────
    const hasSlots = provider.availability_slots?.length > 0;
    const underCapacity = provider.active_bookings < provider.max_daily_bookings;
    const availabilityScore = hasSlots && underCapacity ? 100 : hasSlots ? 50 : 0;

    // ── Review Score ──────────────────────────────────────
    const ratingScore = (provider.rating / 5) * 100;
    const daysSinceReview = Math.floor(
      (new Date() - new Date(provider.last_review_date)) / 86400000
    );
    const recencyBonus = daysSinceReview <= 3 ? 15
      : daysSinceReview <= 7 ? 10
      : daysSinceReview <= 30 ? 5 : 0;
    const reviewScore = Math.min(100, ratingScore + recencyBonus);

    // ── Reliability Score ─────────────────────────────────
    const reliabilityScore = provider.on_time_score * 100;

    // ── Price Score ───────────────────────────────────────
    let priceScore = 70;
    if (parsedIntent.budget_sensitivity === 'high') {
      if (provider.base_rate_pkr <= 700)       priceScore = 100;
      else if (provider.base_rate_pkr <= 1000) priceScore = 70;
      else if (provider.base_rate_pkr <= 1500) priceScore = 45;
      else                                      priceScore = 20;
    } else if (parsedIntent.budget_sensitivity === 'low') {
      priceScore = 80;
    } else {
      priceScore = provider.base_rate_pkr <= 1000 ? 80 : 60;
    }

    // ── Cancellation Score ────────────────────────────────
    const cancellationScore = Math.max(0, 100 - (provider.cancellation_rate * 500));

    // ── Weighted Total ────────────────────────────────────
    const totalScore = (
      distanceScore      * 0.20 +
      availabilityScore  * 0.20 +
      reviewScore        * 0.15 +
      reliabilityScore   * 0.15 +
      specializationScore * 0.15 +
      priceScore         * 0.10 +
      cancellationScore  * 0.05
    );

    return {
      ...provider,
      service_match: serviceMatch,
      complexity_match: complexityMatch,
      complexity_gap: complexityGap,
      requested_complexity: requestedComplexity,
      provider_complexity_levels: providerComplexityLevels,
      computed_score: Math.round(totalScore),
      score_breakdown: {
        distance:       Math.round(distanceScore),
        availability:   Math.round(availabilityScore),
        review:         Math.round(reviewScore),
        reliability:    Math.round(reliabilityScore),
        specialization: Math.round(specializationScore),
        price:          Math.round(priceScore),
        cancellation:   Math.round(cancellationScore),
        total:          Math.round(totalScore)
      }
    };
  });

  scored.sort((a, b) => b.computed_score - a.computed_score);

  multiServiceResults.push({
    service: serviceType,
    requested_complexity: parsedIntent.job_complexity || 'basic',
    top_match: scored[0] || null,
    alternatives: scored.slice(1, 7),
    total_evaluated: scored.length,
    status: scored.length > 0 ? 'providers_found' : 'no_providers_found'
  });
}

return [{ json: {
  status: 'success',
  workflow: 'WF2-ProviderMatching',
  is_multi_service: requestedServices.length > 1,
  services: multiServiceResults,
  service_count: requestedServices.length,
  location: parsedIntent.location || null,
  total_providers_evaluated: providers.length
}}];

// KHADMAT AI — Map Google Places results → provider schema
// active_bookings now sourced from real Supabase data (today's confirmed/in_progress)
const placesResults = $('Places Nearby Search1').first().json.results || [];
const distanceRows = $('Distance Matrix API1').first().json.rows || [];
const intent = $('WF2 — HTTP Trigger1').first().json.body;
const parsedIntent = intent.output || intent;

// ── Build a real active_bookings map from Supabase capacity query ──
// Supabase returns an array of { provider_id } rows (one row per booking).
// We count how many bookings each provider_id has today.
const capacityRows = $input.all().map(r => r.json).filter(r => r && r.provider_id);
const activeBookingsMap = {};
for (const row of capacityRows) {
  const pid = row.provider_id;
  activeBookingsMap[pid] = (activeBookingsMap[pid] || 0) + 1;
}

console.log('=== WF2 Capacity Map ===');
console.log('Providers with active bookings today:', Object.keys(activeBookingsMap).length);
console.log('Capacity map:', JSON.stringify(activeBookingsMap));

const complexityKeywords = {
  'AC installation': 'complex',
  'AC repair': 'intermediate',
  'AC gas refill': 'basic',
  'plumber': 'basic',
  'electrician': 'intermediate',
  'carpenter': 'intermediate',
  'painter': 'basic',
  'tutor': 'basic',
  'beautician': 'basic',
  'generator mechanic': 'intermediate'
};

const MAX_DAILY_BOOKINGS = 4;

const providers = placesResults.map((place, i) => {
  const distanceElement = distanceRows[i]?.elements?.[0];
  const distanceKm = distanceElement?.status === 'OK'
    ? parseFloat((distanceElement.distance.value / 1000).toFixed(1))
    : 5.0;

  const priceLevel = place.price_level ?? 2;
  const baseRateMap = { 0: 400, 1: 600, 2: 900, 3: 1300, 4: 2000 };
  const baseRate = baseRateMap[Math.round(priceLevel)] || 900;

  const rating = place.rating ?? 4.0;
  const reviewCount = place.user_ratings_total ?? 10;

  // ── Real active_bookings from Supabase ──
  const activeBookings = activeBookingsMap[place.place_id] || 0;
  const isAtCapacity = activeBookings >= MAX_DAILY_BOOKINGS;

  // Slots: if provider is at capacity, show no slots
  const isOpen = place.opening_hours?.open_now ?? false;
  const availabilitySlots = isAtCapacity
    ? []
    : isOpen
    ? ['09:00', '11:00', '14:00', '16:00']
    : ['09:00', '11:00'];

  const verified = place.business_status === 'OPERATIONAL';
  const reputationScore = Math.min(99, Math.round(
    (rating / 5) * 70 + Math.min(30, (reviewCount / 100) * 30)
  ));

  return {
    id: place.place_id,
    name: place.name,
    owner: place.name,
    services: parsedIntent.services || [parsedIntent.service_type],
    complexity_levels: (() => {
      const base = complexityKeywords[parsedIntent.service_type] || 'basic';
      const levels = {
        basic: ['basic'],
        intermediate: ['basic', 'intermediate'],
        complex: ['basic', 'intermediate', 'complex']
      };
      return levels[base];
    })(),
    areas: [parsedIntent.location],
    coordinates: {
      lat: place.geometry.location.lat,
      lng: place.geometry.location.lng
    },
    address: place.vicinity,
    base_rate_pkr: baseRate,
    rating: rating,
    review_count: reviewCount,
    last_review_date: new Date().toISOString().split('T')[0],
    on_time_score: Math.min(0.99, 0.70 + (rating - 3.5) * 0.1),
    cancellation_rate: Math.max(0.01, 0.15 - (rating - 3.5) * 0.04),
    availability_slots: availabilitySlots,
    active_bookings: activeBookings,
    max_daily_bookings: MAX_DAILY_BOOKINGS,
    at_capacity: isAtCapacity,
    distance_km: distanceKm,
    verified: verified,
    reputation_score: reputationScore,
    google_maps_url: `https://maps.google.com/?q=${encodeURIComponent(place.name)}`,
    place_id: place.place_id,
    photos: place.photos?.slice(0, 1).map(p =>
      `https://maps.googleapis.com/maps/api/place/photo?maxwidth=400&photoreference=${p.photo_reference}&key=YOUR_KEY`
    ) || []
  };
});

if (providers.length === 0) {
  return [{
    json: {
      providers: [],
      warning: 'Google Places returned 0 results. Check API key and service keyword.',
      location_used: parsedIntent.location,
      service_queried: parsedIntent.service_type
    }
  }];
}

return [{ json: { providers } }];

// KHADMAT AI — WF3 Pricing Agent (inline after WF2) with Multi-Service Support
const matchResult = $input.first().json;
const intent = $('WF2 — HTTP Trigger1').first().json.body;
const parsedIntent = intent.output || intent;

// Handle multi-service structure from Calculate Provider Scores
const servicesArray = matchResult.services || [];

if (servicesArray.length === 0) {
  return [{ json: { status: 'error', message: 'No services found in match result', received: matchResult } }];
}

// Process pricing for each service
const pricedServices = servicesArray.map(serviceResult => {
  const provider = serviceResult.top_match;

  if (!provider) {
    return {
      service: serviceResult.service,
      status: 'no_provider',
      message: 'No provider found for this service'
    };
  }

  const baseRate = provider.base_rate_pkr;

  // 1. Complexity Multiplier
  const complexityMap = { 'basic': 1.0, 'intermediate': 1.3, 'complex': 1.6 };
  const complexityMultiplier = complexityMap[parsedIntent.job_complexity] || 1.0;
  const complexityAddition = Math.round(baseRate * (complexityMultiplier - 1));

  // 2. Surge Pricing (Time-based)
  const currentHour = new Date().getHours();
  const isSurgeTime = (currentHour >= 9 && currentHour <= 11) || (currentHour >= 17 && currentHour <= 19);
  const surgeMultiplier = isSurgeTime ? 1.2 : 1.0;
  const surgeAddition = Math.round((baseRate + complexityAddition) * (surgeMultiplier - 1));

  // 3. Distance Cost
  const distanceCost = Math.round(provider.distance_km * 50);

  const totalPrice = baseRate + complexityAddition + surgeAddition + distanceCost;

  return {
    service: serviceResult.service,
    provider: provider,
    alternatives: serviceResult.alternatives || [],
    pricing: {
      total_pkr: totalPrice,
      breakdown: {
        base_rate: baseRate,
        complexity_extra: complexityAddition,
        surge_extra: surgeAddition,
        distance_extra: distanceCost
      },
      display: `${serviceResult.service}: PKR ${totalPrice} (Base: ${baseRate} + Complexity: ${complexityAddition} + Surge: ${surgeAddition} + Distance: ${distanceCost})`
    }
  };
});

// Calculate multi-service discount if applicable
const isMultiService = pricedServices.length > 1;
const totalBeforeDiscount = pricedServices.reduce((sum, s) => sum + (s.pricing?.total_pkr || 0), 0);
const multiServiceDiscount = isMultiService ? Math.round(totalBeforeDiscount * 0.1) : 0;
const grandTotal = totalBeforeDiscount - multiServiceDiscount;

return [{ 
  json: {
    status: 'success',
    workflow: 'WF3-Pricing',
    is_multi_service: isMultiService,
    services: pricedServices,
    summary: {
      total_services: pricedServices.length,
      subtotal_pkr: totalBeforeDiscount,
      multi_service_discount_pkr: multiServiceDiscount,
      grand_total_pkr: grandTotal,
      location: parsedIntent.location,
      job_complexity: parsedIntent.job_complexity
    }
  }
}];
